import { useState } from 'react';

export function ContextMenu({ children }) {
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
  const items = {{menu_items}};
  return (
    <div onContextMenu={(e) => { e.preventDefault(); setPos({ x: e.clientX, y: e.clientY }); }}>
      {children}
      {pos && (
        <>
          <div className="fixed inset-0" onClick={() => setPos(null)} />
          <ul style={{ top: pos.y, left: pos.x }} className="fixed z-50 w-48 rounded border bg-white py-1 shadow-lg">
            {items.map((it) => (
              <li key={it.label} onClick={() => { it.action(); setPos(null); }}
                className="cursor-pointer px-3 py-1.5 text-sm hover:bg-gray-100">{it.label}</li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}
